// level_to_index: 0..100 -> 0..10 (rounded down to nearest 10)
static inline uint8_t battery_level_to_index(uint8_t pct) {
  if (pct >= 100) return 10;
  if (pct < 10) return 0;
  return (uint8_t)(pct / 10);
}

// Lookup the icon for a given level (0..100).
static inline const uint8_t* battery_icon_for_level(uint8_t pct) {
  static const uint8_t* const LUT[11] = {
    battery_icon_000,  // 0%
    battery_icon_010,  // 10%
    battery_icon_020,  // 20%
    battery_icon_030,  // 30%
    battery_icon_040,  // 40%
    battery_icon_050,  // 50%
    battery_icon_060,  // 60%
    battery_icon_070,  // 70%
    battery_icon_080,  // 80%
    battery_icon_090,  // 90%
    battery_icon_100,  // 100%
  };
  return LUT[battery_level_to_index(pct)];
}

